(function(){
function M(c, q, o, a, vq, ov, va, n){ var it = {c:c, q:q, o:o, a:a, vq:vq, ov:ov, va:va}; if (n) it.n = n; return it; }

window.THI_HW = {id:'hw', icon:'🏠', vi:'Homework TWI Paper 1–3 (120 câu: trắc nghiệm + điền khuyết)', en:'TWI Homework papers 1–3', type:'mcq', items:[
/* ===================== PAPER 1 ===================== */
M(5,'P1-1. Which is the best destructive test for showing lack of sidewall fusion in a 25mm thickness butt weld?',['Nick break.','Side bend.','Charpy impact.','Face bend test.'],1,'Phép thử phá hủy nào tốt nhất để phát hiện không ngấu thành vát (lack of sidewall fusion) ở mối hàn giáp mối dày 25 mm?',['Thử bẻ gãy có khía (nick break)','Thử uốn cạnh (side bend)','Thử va đập Charpy','Thử uốn mặt (face bend)'],'Tấm dày ≥12 mm dùng UỐN CẠNH: mặt cắt ngang toàn chiều dày bị kéo, nên vách vát không ngấu sẽ mở ra. Uốn mặt/đáy chỉ thử được bề mặt; Charpy đo độ dai; nick break dùng cho thợ hàn với mối mỏng.'),
M(5,'P1-1a. With reference to the previous question, what type of test is this?',['Qualitative','Tentative','Quantitative','Sensitive'],0,'Theo câu trước, đây là loại phép thử gì?',['Định tính','Thăm dò','Định lượng','Nhạy'],'Uốn là phép thử ĐỊNH TÍNH (qualitative): chỉ đánh giá đạt/không đạt, không ra con số. Định lượng (quantitative) = kéo, va đập, độ cứng, cho ra giá trị số.'),
M(4,'P1-2. Which of the following would be cause for rejection by most fabrication standards when inspecting fillet welds with undercut, a small amount of?',['Depth.','Length.','Width.','Sharpness.'],3,'Khi kiểm tra mối hàn góc có cháy chân, chỉ cần một chút yếu tố nào dưới đây là đa số tiêu chuẩn chế tạo loại bỏ?',['Chiều sâu','Chiều dài','Chiều rộng','Độ sắc (đáy rãnh nhọn)'],'Tiêu chuẩn cho phép cháy chân với giới hạn sâu/dài nhưng luôn yêu cầu "chuyển tiếp mượt, không có chỉ thị sắc" (smooth blend, no sharp indications). Cháy chân SẮC tạo tập trung ứng suất → loại ngay dù nhỏ.'),
M(4,'P1-2a. With reference to the previous question, what would be the most likely cause of undercut?',['High inductance','High wire feed speed','Low inductance','Low voltage'],1,'Theo câu trước, nguyên nhân có khả năng nhất gây cháy chân là gì?',['Điện cảm cao','Tốc độ cấp dây cao','Điện cảm thấp','Điện áp thấp'],'Cháy chân do dòng hàn quá cao, điện áp/hồ quang quá dài, tốc độ hàn quá nhanh. Trong MIG/MAG tốc độ cấp dây cao = dòng hàn cao → cháy chân. Điện áp thấp làm hồ quang ngắn, hẹp → không gây cháy chân; điện cảm chỉ ảnh hưởng bắn tóe/độ ngấu ở chế độ dip.','(†) Đề không có "dòng cao/áp cao"; chọn phương án gần nhất là tốc độ cấp dây cao (= dòng cao).'),
M(0,'P1-3. The European Standard for NDE of fusion welds by visual examination is:',['EN 15614.','EN 2560.','EN 9606.','EN 17637.'],3,'Tiêu chuẩn châu Âu về kiểm tra không phá hủy mối hàn nóng chảy bằng ngoại quan là:',['EN 15614 (chứng nhận quy trình hàn)','EN 2560 (que hàn MMA)','EN 9606 (chứng nhận thợ hàn)','EN 17637 (kiểm tra ngoại quan)'],'(BS EN) ISO 17637 = Visual testing of fusion-welded joints: tầm nhìn ≤600 mm, góc ≥30°, ánh sáng tối thiểu 350 lux (khuyến nghị 500), kính lúp ×2–×5.'),
M(7,'P1-3a. With reference to the previous question, two of the standards are closely linked to each other, which are they?',['a and b','b and c','a and c','a and d'],2,'Theo câu trước, hai tiêu chuẩn nào liên quan chặt với nhau?',['a và b','b và c','a và c (15614 & 9606)','a và d'],'EN ISO 15614 (chứng nhận QUY TRÌNH) và EN ISO 9606 (chứng nhận THỢ HÀN) là cặp tiêu chuẩn chứng nhận đi cùng nhau: thợ hàn mẫu PQR thường được cấp luôn chứng chỉ 9606.'),
M(4,'P1-4. When visually inspecting the face of a finished weld which of the following flaws would be considered the most serious:',['Excess weld metal height.','Start porosity.','Spatter.','Arc strike.'],3,'Khi kiểm tra ngoại quan bề mặt mối hàn hoàn chỉnh, khuyết tật nào nghiêm trọng nhất?',['Chiều cao kim loại đắp dư','Rỗ khí đầu đường hàn','Bắn tóe','Vết mồi hồ quang (arc strike)'],'Vết mồi hồ quang nguội cực nhanh → điểm cứng martensite, có thể có nứt nhỏ → khởi phát nứt mỏi/giòn. Bảng tiêu chí TWI: arc strike KHÔNG được phép (not permitted) ở mọi nhóm.'),
M(4,'P1-4a. With reference to the previous question and the correct answer, why is it considered so?',['It looks bad','It’s a hard spot','Its lack of fusion','It’s a volumetric defect'],1,'Theo câu trước, vì sao nó nghiêm trọng?',['Trông xấu','Là điểm cứng cục bộ','Là không ngấu','Là khuyết tật khối'],'Điểm cứng (hard spot): kim loại bị chảy rồi nguội nhanh bởi khối thép nguội xung quanh → martensite cứng giòn, nguy cơ nứt.'),
M(4,'P1-5. Which of the following is a planar imperfection?',['Lack of sidewall fusion.','Slag inclusion.','Linear porosity.','Root concavity.'],0,'Khuyết tật nào sau đây là khuyết tật phẳng (planar)?',['Không ngấu thành vát','Ngậm xỉ','Rỗ khí thẳng hàng','Lõm đáy'],'Khuyết tật PHẲNG: nứt, không ngấu (thành vát, giữa lớp, đáy), lamination — có 2 chiều, đầu sắc → nguy hiểm, UT phát hiện tốt. Xỉ, rỗ = khuyết tật KHỐI (volumetric). Lõm đáy = sai hình dạng.'),
M(4,'P1-5a. With reference to the previous question and the correct answer, how could this defect be caused?',['Amperage to high','Voltage too high','Amperage too low','Gas flow rate too low'],2,'Theo câu trước, khuyết tật đó có thể do nguyên nhân gì?',['Dòng hàn quá cao','Điện áp quá cao','Dòng hàn quá thấp','Lưu lượng khí quá thấp'],'Không ngấu thành vát: nhiệt không đủ ở mép vũng hàn — dòng thấp, tốc độ hàn nhanh, góc mỏ sai, điện cảm quá cao ở MAG dip. Khí thấp → rỗ; dòng cao → cháy chân, thủng.'),
M(15,'P1-6. A fillet weld has an actual throat thickness of 8mm and a leg length of 7mm, what is the excess weld metal?',['2.1mm.','1.8mm.','3.1mm.','1.4mm.'],2,'Mối hàn góc có chiều cao tính toán thực tế (actual throat) 8 mm, cạnh (leg length) 7 mm. Kim loại đắp dư là bao nhiêu?',['2,1 mm','1,8 mm','3,1 mm','1,4 mm'],'Chiều cao thiết kế (design throat) = 0,7 × cạnh = 0,7 × 7 = 4,9 mm. Kim loại đắp dư = 8 − 4,9 = 3,1 mm.'),
M(15,'P1-6a. With reference to the previous question and the correct answer, if this excess weld metal was removed the fillet would be a?',['Concave fillet weld','Convex fillet weld','Mitre','Undersized fillet weld'],2,'Theo câu trước, nếu bỏ phần kim loại đắp dư thì mối hàn góc sẽ là?',['Mối góc lõm','Mối góc lồi','Mối góc phẳng (mitre)','Mối góc thiếu kích thước'],'Mitre fillet = mặt phẳng, tiết diện tam giác vuông cân; kim loại đắp dư là phần lồi nằm trên đường mitre. Bỏ phần lồi → còn đúng mối mitre.'),
M(0,'P1-7. BS EN 17637 allows the use of a magnifying glass for visual inspection, but recommends that the magnification is:',['X 2.','X 2 to x5.','X 5 to x10.','Not greater than x20.'],1,'BS EN 17637 cho phép dùng kính lúp khi kiểm tra ngoại quan, khuyến nghị độ phóng đại là:',['×2','×2 đến ×5','×5 đến ×10','Không quá ×20'],'ISO 17637: kính lúp ×2 – ×5.'),
M(0,'P1-7a. With reference to the previous question, what likely defect will this help to find?',['Excess weld metal height','Undercut','Internal lack of fusion','Root concavity'],1,'Theo câu trước, kính lúp giúp phát hiện khuyết tật nào?',['Chiều cao đắp dư','Cháy chân','Không ngấu bên trong','Lõm đáy'],'Kính lúp chỉ thấy bề mặt và chi tiết nhỏ: cháy chân, nứt nhỏ, rỗ bề mặt. Khuyết tật bên trong cần RT/UT; đắp dư và lõm đáy đo bằng dưỡng.'),
M(7,'P1-8. A WPS may specify a maximum width for individual weld beads (weave width) when welding CMn steels. If the width is exceeded it may cause:',['Lack of inter-run fusion.','A reduction in HAZ toughness.','Lack of sidewall fusion.','Too low a deposition rate.'],1,'WPS có thể quy định bề rộng tối đa của từng đường hàn (bề rộng dao động) khi hàn thép C-Mn. Nếu vượt quá có thể gây:',['Không ngấu giữa các lớp','Giảm độ dai vùng HAZ','Không ngấu thành vát','Tốc độ đắp quá thấp'],'Dao động rộng → tốc độ tiến chậm → NHIỆT LƯỢNG ĐƯA VÀO cao → hạt HAZ thô → giảm độ dai. Đó là lý do WPS giới hạn bề rộng dao động (kiểm soát heat input).'),
M(1,'P1-8a. With reference to the previous question and the correct answer, in what welding position is this most likely to happen?',['PA','PB','PF','PG'],2,'Theo câu trước, điều này dễ xảy ra nhất ở tư thế nào?',['PA (bằng)','PB (góc ngang)','PF (đứng hàn lên)','PG (đứng hàn xuống)'],'PF (hàn đứng từ dưới lên) phải dao động rộng, tiến chậm → heat input cao nhất. PG (hàn xuống) nhanh, heat input thấp nhất.'),
M(1,'P1-9. In TIG welding a current slope-out device reduces:',['Tungsten spatter.','Risk of crater cracking.','Risk of arc strikes.','Interpass temperature.'],1,'Trong hàn TIG, thiết bị giảm dòng cuối đường hàn (slope-out) làm giảm:',['Bắn tóe vonfram','Nguy cơ nứt hõm cuối','Nguy cơ vết mồi hồ quang','Nhiệt độ giữa các lớp'],'Slope-out giảm dòng từ từ, vũng hàn nhỏ và nông dần → kết tinh thuận lợi → tránh nứt hõm cuối (crater crack) và lõm co (crater pipe). Slope-up (tăng dòng đầu) chống sốc nhiệt vonfram.'),
M(1,'P1-9a. With reference to the previous question and the correct answer, what other device is working at the same time?',['Gas flow','Slope up device','High frequency','Pre purge'],0,'Theo câu trước, thiết bị nào khác cùng hoạt động lúc đó?',['Khí bảo vệ (post-flow, khí thổi sau)','Thiết bị tăng dòng đầu','Mồi cao tần','Thổi khí trước (pre-purge)'],'Cuối đường hàn khí bảo vệ vẫn chảy (post-flow) để che hõm cuối và điện cực vonfram đang nguội khỏi oxy hóa. Slope-up, HF, pre-purge chỉ hoạt động lúc BẮT ĐẦU.','(†) Đáp án suy luận theo chức năng thiết bị TIG.'),
M(1,'P1-10. Pipe bores of some materials must be purged with argon before and during TIG welding to:',['Prevent linear porosity.','Prevent burn-through.','Prevent oxidation of the root bead.','Eliminate moisture pick-up in the root bead.'],2,'Lòng ống của một số vật liệu phải thổi khí argon trước và trong khi hàn TIG để:',['Chống rỗ thẳng hàng','Chống thủng','Chống oxy hóa đường hàn đáy','Loại bỏ hút ẩm ở đường hàn đáy'],'Khí lót (back purge) chống oxy hóa mặt đáy ("đường đáy cháy đen/sugaring") ở thép không gỉ, titan, hợp kim niken.'),
M(1,'P1-10a. With reference to the previous question and the correct answer, what material would this pipe be?',['All materials','Aluminium and stainless steel','Stainless steel','Carbon steel and stainless steel'],2,'Theo câu trước, ống đó là vật liệu gì?',['Mọi vật liệu','Nhôm và thép không gỉ','Thép không gỉ','Thép cacbon và thép không gỉ'],'Thép không gỉ (và duplex, titan) bắt buộc thổi khí lót. Thép cacbon và nhôm thường không cần.'),
M(3,'P1-11. According to AWS 2.4 a weld symbol for the other side is placed:',['Above the dashed line.','Below the dashed line.','Above the solid line.','Below the solid line.'],2,'Theo AWS A2.4, ký hiệu mối hàn phía bên kia (other side) đặt ở đâu?',['Trên đường đứt nét','Dưới đường đứt nét','Trên đường liền','Dưới đường liền'],'AWS chỉ có MỘT đường tham chiếu liền: phía mũi tên ký hiệu đặt DƯỚI, phía bên kia đặt TRÊN. Không có đường đứt nét (đó là của ISO 2553).'),
M(3,'P1-11a. With reference to the previous question, when is the dashed line removed?',['When the welds are symmetrical','There is no dashed line','When it’s a butt weld','When the fillet welds are different sizes'],0,'Theo câu trước, khi nào bỏ đường đứt nét?',['Khi mối hàn đối xứng (hai phía như nhau)','Không có đường đứt nét','Khi là mối giáp mối','Khi hai mối hàn góc khác kích thước'],'Theo ISO 2553 đường đứt nét được bỏ khi mối hàn đối xứng hai phía (ví dụ X, K, hai mối góc bằng nhau).','(†) Nếu hiểu câu hỏi chỉ theo AWS thì "không có đường đứt nét" cũng đúng; nhưng câu hỏi "khi nào bỏ" chỉ có nghĩa với ISO.'),
M(8,'P1-12. Which of the following elements is added to steel to give resistance to creep at elevated service temperatures?',['Nickel.','Manganese.','Molybdenum.','Aluminium.'],2,'Nguyên tố nào thêm vào thép để chống rão (creep) khi làm việc ở nhiệt độ cao?',['Niken','Mangan','Molypden','Nhôm'],'Mo (~0,5–1%) chống rão; Cr chống oxy hóa ở nhiệt độ cao. Ni: dai ở nhiệt độ thấp; Mn: độ bền + khử S; Al: khử oxy, làm mịn hạt.'),
M(8,'P1-12a. With reference to the previous question, what is creep?',['It’s a form of sensitization','It’s a form of deformation','It’s a rupture','It’s a type of corrosion'],1,'Theo câu trước, rão (creep) là gì?',['Một dạng nhạy hóa','Một dạng biến dạng','Là sự đứt gãy','Một kiểu ăn mòn'],'Rão = biến dạng dẻo chậm, liên tục theo thời gian dưới ứng suất không đổi ở nhiệt độ cao; cuối cùng mới dẫn đến đứt rão (creep rupture).'),
M(15,'P1-13. Compound fillet welds:',['Always contain full penetration butt welds.','Joints which always have combinations of welds made by different welding processes.','Combinations between two different weld types.','All of the above.'],2,'Mối hàn hỗn hợp (compound weld):',['Luôn chứa mối giáp mối thấu hoàn toàn','Mối nối luôn kết hợp các mối hàn bằng quá trình khác nhau','Kết hợp hai loại mối hàn khác nhau','Tất cả các ý trên'],'WIS5 2.6.3: compound = kết hợp mối GIÁP MỐI + mối GÓC (ví dụ T vát mép rồi phủ góc), thấu hoàn toàn HOẶC một phần. Không bắt buộc thấu hoàn toàn, không liên quan quá trình hàn.'),
M(11,'P1-13a. With reference to the previous question and the correct answer, what would be the typical bevel angle for a compound fillet weld?',['30° degrees','35° degrees','40° degrees','50° degrees'],1,'Theo câu trước, góc vát điển hình cho mối hàn hỗn hợp là?',['30°','35°','40°','50°'],'Mối T vát mép (single/double bevel) thường vát 35° (dung sai thường 35° ±5°) để que/mỏ tiếp cận chân mối mà vẫn ít kim loại đắp.','(†) Sách WIS5 không ghi số cụ thể; 35° là giá trị điển hình trong slide TWI cho mối T vát mép. Trên 45° hiếm dùng.'),
M(0,'P1-14. Welding inspectors:',['Normally supervise welders.','Are normally requested to write welding procedures.','Are sometimes requested to qualify welders.','All of the above.'],2,'Thanh tra hàn:',['Thường giám sát thợ hàn','Thường được yêu cầu viết quy trình hàn','Đôi khi được yêu cầu chứng nhận thợ hàn','Tất cả các ý trên'],'Thanh tra KHÔNG giám sát thợ (việc của giám sát/đốc công) và KHÔNG viết WPS (việc của kỹ sư hàn), nhưng ĐÔI KHI được yêu cầu chứng kiến/chứng nhận thợ hàn.'),
M(7,'P1-14a. With reference to the previous question, what standard would be used?',['ASME 8','EN 2650','EN 9606','EN 15614'],2,'Theo câu trước, sẽ dùng tiêu chuẩn nào?',['ASME VIII (bình chịu áp)','EN 2650 (sai số hiệu)','EN 9606 (chứng nhận thợ hàn)','EN 15614 (chứng nhận quy trình)'],'Chứng nhận thợ hàn: EN ISO 9606 (thép là 9606-1). Mỹ dùng ASME IX hoặc AWS D1.1, không phải ASME VIII.'),
M(1,'P1-15. In an arc welding process, which of the following is the correct term used for the amount of weld metal deposited?',['Filling rate.','Deposition rate.','Weld deposition.','Weld duty cycle.'],1,'Trong hàn hồ quang, thuật ngữ đúng cho lượng kim loại hàn được đắp là gì?',['Tốc độ điền đầy','Tốc độ đắp (deposition rate)','Kim loại đắp','Chu kỳ làm việc'],'Deposition rate = khối lượng kim loại đắp trên một đơn vị thời gian. Duty cycle là thời gian máy chạy được ở dòng định mức trong 10 phút.'),
M(1,'P1-15a. With reference to the previous question and the correct answer, how is this measured?',['Kg per mm','Kg per hour','A percentage of 10 minutes','Millilitres per 100 grms of weld'],1,'Theo câu trước, đại lượng đó đo bằng đơn vị gì?',['kg/mm','kg/giờ','% của 10 phút','ml/100 g kim loại hàn'],'Tốc độ đắp đo bằng kg/giờ. "% của 10 phút" là duty cycle; "ml/100 g" là hàm lượng hydro.'),
/* ----- Paper 1 điền khuyết ----- */
M(0,'P1-25. Magnification in the range of _______ can be used when visually inspecting welds.',['X2 to X5','X5 to X10','X3 to X6','X8 to X12'],0,'Có thể dùng độ phóng đại trong khoảng ___ khi kiểm tra ngoại quan mối hàn.',['×2 đến ×5','×5 đến ×10','×3 đến ×6','×8 đến ×12'],'ISO 17637: ×2 – ×5.'),
M(4,'P1-26. Too ___________ could cause lack of penetration.',['Large an electrode','much amperage','little gas shield','large a bevel angle'],0,'Quá ___ có thể gây không thấu.',['lớn đường kính que','nhiều dòng hàn','ít khí bảo vệ','lớn góc vát'],'Que quá to không xuống tới chân mối → không thấu. Dòng cao gây thủng/thấu quá; ít khí → rỗ; góc vát lớn giúp thấu tốt hơn.'),
M(11,'P1-27. The included angle on ________ is increased to avoid lack of fusion.',['Stainless steel','HSLA steels','CMn steels','Aluminium'],3,'Góc rãnh (included angle) của ___ được tăng lên để tránh không ngấu.',['Thép không gỉ','Thép HSLA','Thép C-Mn','Nhôm'],'Nhôm dẫn nhiệt rất cao, nhiệt tản nhanh → dễ không ngấu; dùng góc rãnh lớn (70–90°) để hồ quang tác dụng trực tiếp lên thành vát.'),
M(1,'P1-28. In TIG welding _______, tungsten inclusions can occur.',['Not using the slope up','Using a high gas flow rate','using a high frequency','using alternating current'],0,'Trong hàn TIG, ___ có thể gây ngậm vonfram.',['không dùng tăng dòng đầu (slope-up)','dùng lưu lượng khí cao','dùng mồi cao tần','dùng dòng xoay chiều'],'Mồi hồ quang với dòng đầy ngay → sốc nhiệt vonfram, mảnh vonfram bắn vào vũng hàn. Slope-up "giảm hoặc ngăn sốc nhiệt cho vonfram" (slide Handout). Mồi cao tần ngược lại giúp TRÁNH chạm vonfram.'),
M(1,'P1-29. A _________ can cause excessive spatter in MIG/MAG welding.',['High inductance','low inductance','short CTWD','pulse current'],1,'___ có thể gây bắn tóe nhiều khi hàn MIG/MAG.',['Điện cảm cao','Điện cảm thấp','Tầm với điện cực (CTWD) ngắn','Dòng xung'],'Điện cảm làm CHẬM tốc độ tăng dòng khi ngắn mạch. Điện cảm THẤP → dòng tăng vọt → đầu dây nổ tung → bắn tóe nhiều. Điện cảm quá cao → không ngấu. Dòng xung giảm bắn tóe.'),
M(5,'P1-30. A fillet fracture test is designed as a _______ type of test.',['Qualitative','purnative','quantitative','subjective'],0,'Thử bẻ gãy mối hàn góc (fillet fracture) là loại thử ___.',['định tính','(từ sai, không tồn tại)','định lượng','chủ quan'],'Bẻ gãy mối góc để xem bề mặt gãy (ngấu chân, rỗ, xỉ) → đánh giá đạt/không → ĐỊNH TÍNH.'),
M(5,'P1-31. A ________ is designed for use on butt welds.',['Fracture test','nick break test','peel test','pull test'],1,'___ được thiết kế dùng cho mối hàn giáp mối.',['Thử bẻ gãy (mối góc)','Thử bẻ gãy có khía (nick break)','Thử bóc tách (peel, hàn điểm)','Thử kéo đứt'],'Nick break: cưa khía hai bên mối giáp mối rồi bẻ gãy để xem bề mặt trong. Fillet fracture dành cho mối góc; peel test cho hàn điểm.'),
M(5,'P1-32. A nick break test is designed as a ________ type of test.',['Purnative','qualitative','subjective','quantitative'],1,'Thử nick break là loại thử ___.',['(từ sai)','định tính','chủ quan','định lượng'],'Nick break cho kết quả quan sát (có/không khuyết tật trên mặt gãy) → định tính.'),
M(5,'P1-33. A _________ flaw is more likely to be found by a nick break test.',['Undercut','underfill','lack of fusion','crater crack'],2,'Khuyết tật ___ dễ được phát hiện bằng thử nick break hơn.',['Cháy chân','Thiếu điền đầy','Không ngấu','Nứt hõm cuối'],'Bề mặt gãy đi qua bên trong mối hàn nên lộ ra không ngấu, rỗ, xỉ. Cháy chân/thiếu điền đầy là bề mặt, thấy bằng ngoại quan.'),
M(6,'P1-34. Using the radiographic NDT method and a double wall single image exposure, the film goes outside and the source goes _________.',['Inside','around the total circumference','outside','both sides'],2,'Chụp phóng xạ kiểu xuyên hai thành – một ảnh (DWSI): phim đặt bên ngoài và nguồn đặt ___.',['bên trong','quanh toàn chu vi','bên ngoài','hai phía'],'DWSI: nguồn và phim đều NGOÀI ống (đối diện nhau); tia đi qua hai thành nhưng chỉ ảnh thành sát phim được đánh giá. Nguồn đặt TRONG ống là SWSI/panoramic.'),
/* ===================== PAPER 2 ===================== */
M(8,'P2-1. The maximum hardness in the HAZ of a steel will increase if:',['Heat input is increased.','CEV is increased.','Joint thickness is decreased.','Basic electrode are used'],1,'Độ cứng lớn nhất vùng HAZ của thép sẽ tăng nếu:',['Tăng nhiệt lượng đưa vào','Tăng đương lượng cacbon (CEV)','Giảm chiều dày mối nối','Dùng que basic'],'CEV cao → thép dễ tôi (hardenability cao) → HAZ cứng hơn. Tăng heat input và giảm chiều dày làm nguội CHẬM → giảm độ cứng; que basic chỉ giảm hydro.'),
M(8,'P2-1a. With reference to the previous question, what else can also cause this condition?',['Low heat input','Slow travel speed','High pre heat','High amperages'],0,'Theo câu trước, yếu tố nào khác cũng gây ra tình trạng này?',['Nhiệt lượng đưa vào thấp','Tốc độ hàn chậm','Gia nhiệt sơ bộ cao','Dòng hàn cao'],'Heat input thấp → nguội nhanh → HAZ cứng (martensite). Ba phương án còn lại đều làm nguội chậm.'),
M(1,'P2-2. Initiation of a TIG arc using a high frequency spark may not be allowed because it:',['Often causes tungsten inclusions.','Can damage electronic equipment.','Is an electrical safety hazard.','Often causes stop/start porosity.'],1,'Mồi hồ quang TIG bằng tia lửa cao tần có thể không được phép vì nó:',['Thường gây ngậm vonfram','Có thể làm hỏng thiết bị điện tử','Là nguy cơ an toàn điện','Thường gây rỗ đầu–cuối'],'Cao tần (HF) phát nhiễu điện từ, gây hỏng/nhiễu thiết bị điện tử, máy tính, thiết bị y tế gần đó → nhiều nơi cấm, phải dùng lift-arc.'),
M(1,'P2-2a. With reference to the previous question, what does this function help with?',['Cathodic cleaning','Penetration','Arc initiation','Crater filling'],2,'Theo câu trước, chức năng này giúp gì?',['Làm sạch catot','Độ thấu','Mồi hồ quang','Điền hõm cuối'],'HF tạo tia lửa ion hóa khe khí giúp MỒI hồ quang không cần chạm vonfram vào vật hàn (tránh ngậm vonfram). Với AC nó còn giúp duy trì hồ quang.'),
M(1,'P2-3. In friction welding, the metal at the interface when the joining occurs is described as being in the:',['Liquid state.','Intercritical state.','Plastic state.','Elastic state.'],2,'Trong hàn ma sát, kim loại ở mặt tiếp xúc khi liên kết hình thành ở trạng thái:',['Lỏng','Liên tới hạn','Dẻo','Đàn hồi'],'Hàn ma sát là hàn TRẠNG THÁI RẮN: kim loại nóng lên đến trạng thái DẺO rồi ép rèn lại, không nóng chảy.'),
M(1,'P2-3a. With reference to the previous question, what is the advantage of this welding Process?',['High deposition rate','Improved properties','Highly transportable','Bulk pack wire feed systems can be used'],1,'Theo câu trước, ưu điểm của quá trình này là gì?',['Tốc độ đắp cao','Cơ tính được cải thiện','Rất cơ động','Dùng được cuộn dây lớn'],'Không nóng chảy → không có tổ chức đúc, không rỗ/nứt kết tinh, hạt mịn do rèn → cơ tính tốt; hàn được kim loại khác loại. Không có kim loại đắp nên không có "tốc độ đắp".'),
M(8,'P2-4. What four criteria are necessary to produce hydrogen induced cold cracking?',['Hydrogen, moisture, martensitic grain structure and heat.','Hydrogen, poor weld profiles, temperatures above 200oC and a slow cooling rate.','Hydrogen, a grain structure susceptible to cracking, stress and a temperature below 300oC.','Hydrogen, existing weld defects, stress and a grain structure susceptible to cracking.'],2,'Bốn điều kiện cần để xảy ra nứt nguội do hydro (HICC) là gì?',['Hydro, ẩm, tổ chức martensite và nhiệt','Hydro, biên dạng xấu, nhiệt độ trên 200 °C và nguội chậm','Hydro, tổ chức nhạy nứt, ứng suất và nhiệt độ dưới 300 °C','Hydro, khuyết tật có sẵn, ứng suất và tổ chức nhạy nứt'],'Bốn yếu tố: HYDRO (>15 ml/100 g) + tổ chức NHẠY (cứng >400 HV) + ỨNG SUẤT (>0,5 giới hạn chảy) + NHIỆT ĐỘ thấp (<300 °C). Bỏ một yếu tố là không nứt.'),
M(8,'P2-4a. With reference to the previous question, why is temperature important in this Cracking mechanism?',['At low temperatures the hydrogen is less mobile','At high temperatures the hydrogen is less mobile','At low temperatures grain growth occurs','At high temperatures more hydrogen is absorbed'],0,'Theo câu trước, vì sao nhiệt độ quan trọng trong cơ chế nứt này?',['Ở nhiệt độ thấp hydro kém linh động (khó thoát ra)','Ở nhiệt độ cao hydro kém linh động','Ở nhiệt độ thấp hạt lớn lên','Ở nhiệt độ cao hấp thụ nhiều hydro hơn'],'Trên ~300 °C hydro khuếch tán nhanh và thoát ra ngoài. Dưới 300 °C hydro kém linh động, bị kẹt lại, tụ ở vùng cứng → nứt. Vì vậy gia nhiệt và giữ nhiệt sau hàn giúp hydro thoát.'),
M(10,'P2-5. Austenitic stainless steels are more susceptible to distortion when compared to ferritic steels this is because:',['High coefficient of thermal expansion, low thermal conductivity.','High coefficient of thermal expansion, high thermal conductivity.','Low coefficient of thermal expansion, high thermal conductivity.','Low coefficient thermal expansion, low thermal conductivity.'],0,'Thép không gỉ austenit dễ biến dạng hơn thép ferit vì:',['Hệ số giãn nở nhiệt cao, dẫn nhiệt thấp','Giãn nở cao, dẫn nhiệt cao','Giãn nở thấp, dẫn nhiệt cao','Giãn nở thấp, dẫn nhiệt thấp'],'Inox austenit giãn nở ~1,5 lần thép cacbon và dẫn nhiệt chỉ ~1/3 → nhiệt tập trung, co giãn mạnh → biến dạng lớn (WIS5 19.4.1).'),
M(8,'P2-5a. With reference to the previous question and the correct answer, do these features make it more susceptible to hydrogen cracking?',['It depends on the welding process','It does not harden on cooling therefore, no.','It depends on the CEV value','Pre heating will be critical to avoid hydrogen cracking'],1,'Theo câu trước, các đặc điểm đó có làm thép dễ nứt hydro hơn không?',['Tùy quá trình hàn','Không, vì nó không tôi cứng khi nguội','Tùy giá trị CEV','Gia nhiệt sơ bộ là then chốt để tránh nứt hydro'],'Austenit không chuyển biến thành martensite khi nguội (không tôi cứng) và hòa tan hydro tốt → hầu như không nứt nguội hydro, không cần gia nhiệt sơ bộ.'),
M(5,'P2-6. All weld tensile test:',['Is used to measure the ultimate tensile strength.','Is used to measure the elongation of the sample.','Is used to measure the yield strength of a sample.','All of the above.'],3,'Thử kéo toàn kim loại mối hàn (all-weld tensile):',['Dùng để đo giới hạn bền kéo','Dùng để đo độ giãn dài của mẫu','Dùng để đo giới hạn chảy của mẫu','Tất cả các ý trên'],'Mẫu all-weld lấy hoàn toàn trong kim loại mối hàn, đo đủ: giới hạn chảy (Re/Rp0.2), bền kéo (Rm) và độ giãn dài A%. (Kéo ngang mối hàn chỉ đo Rm.)'),
M(5,'P2-6a. With reference to the previous question, what is the UTS of a material?',['The maximum load applied per area','The point of failure','The proof stress of the material','Where permanent deformation has occurred'],0,'Theo câu trước, giới hạn bền kéo (UTS) của vật liệu là gì?',['Tải lớn nhất chia cho diện tích','Điểm đứt','Giới hạn chảy quy ước','Điểm bắt đầu biến dạng vĩnh viễn'],'UTS (Rm) = tải trọng LỚN NHẤT / diện tích tiết diện ban đầu (N/mm²). Điểm biến dạng vĩnh viễn = giới hạn chảy.'),
M(8,'P2-7. In the welding of austenitic stainless steels, the consumables and plate materials are often specified to be low carbon content. The reason for this:',['To prevent the formation of cracks in the HAZ.','To prevent the formation of chromium carbides.','To prevent cracking in the weld.','Minimise distortion.'],1,'Khi hàn thép không gỉ austenit, vật liệu hàn và tấm thường được chỉ định loại cacbon thấp. Lý do:',['Chống nứt HAZ','Chống tạo cacbit crom','Chống nứt mối hàn','Giảm biến dạng'],'Ở 600–850 °C cacbon kết hợp crom thành cacbit crom ở biên hạt → biên hạt nghèo Cr → ăn mòn giữa hạt (weld decay). Cacbon thấp (L grade, <0,04% theo slide) thì không đủ C để tạo cacbit.'),
M(8,'P2-7a. With reference to the previous question, what is this type of mechanism know as?',['Creep','Weld decay','Solidification cracking','Crevice corrosion'],1,'Theo câu trước, cơ chế này gọi là gì?',['Rão','Weld decay (ăn mòn giữa hạt vùng HAZ)','Nứt kết tinh','Ăn mòn khe'],'Weld decay = ăn mòn giữa hạt (intergranular corrosion) ở HAZ thép không gỉ bị nhạy hóa (sensitisation).'),
M(7,'P2-8. Essential variable:',['In a WPS may change the properties of the weld.','In a WPS may influence the visual acceptance.','In a WPS may require re-approval of a weld procedure.','All of the above.'],3,'Biến số thiết yếu (essential variable):',['Trong WPS có thể làm thay đổi cơ tính mối hàn','Trong WPS có thể ảnh hưởng đến chấp nhận ngoại quan','Trong WPS có thể đòi hỏi chứng nhận lại quy trình','Tất cả các ý trên'],'WIS5 6.2: biến số ảnh hưởng CƠ TÍNH, thay đổi vượt giới hạn phải CHỨNG NHẬN LẠI WPS. Đáp án đề TWI thường là "All of the above" vì thay đổi biến số thiết yếu (quá trình, tư thế…) cũng thay đổi hình dạng mối hàn.','(†) Định nghĩa chặt chỉ gồm a và c; nếu đề có "both a and c" thì chọn phương án đó.'),
M(7,'P2-8a. With reference to the previous question and the correct answer, which of the following is not an essential variable?',['Heat input','Current type','Cleaning method','Mode of metal transfer'],2,'Theo câu trước, yếu tố nào KHÔNG phải biến số thiết yếu?',['Nhiệt lượng đưa vào','Loại dòng điện','Phương pháp làm sạch','Chế độ chuyển dịch kim loại'],'Phương pháp làm sạch (chải, mài) là biến số KHÔNG thiết yếu — phải ghi trên WPS nhưng đổi không cần chứng nhận lại. Heat input (khi có yêu cầu va đập/độ cứng), loại dòng, chế độ chuyển dịch là thiết yếu.'),
M(5,'P2-9. In an all weld metal tensile test, the original test specimens gauge length is 50mm. After testing the gauge length increased to 72mm, what is the elongation percentage?',['44%.','144%.','69.4%.','2.27%.'],0,'Thử kéo toàn kim loại mối hàn: chiều dài cữ ban đầu 50 mm, sau thử tăng lên 72 mm. Độ giãn dài phần trăm là?',['44%','144%','69,4%','2,27%'],'A% = (72 − 50) / 50 × 100 = 22/50 × 100 = 44%.'),
M(5,'P2-9a. With reference to the previous question, what is exactly being measured here?',['Ultimate tensile strength','Yield strength','Ductility','Toughness'],2,'Theo câu trước, ở đây thực chất đo cái gì?',['Giới hạn bền kéo','Giới hạn chảy','Độ dẻo','Độ dai'],'Độ giãn dài (và độ thắt tiết diện) là thước đo ĐỘ DẺO (ductility). Độ dai đo bằng va đập Charpy.'),
M(1,'P2-10. Which of the following will vary the most when varying the arc length using the MMA welding process?',['Voltage.','Amperage.','Polarity.','Both a and b.'],0,'Khi thay đổi chiều dài hồ quang trong hàn MMA, đại lượng nào thay đổi nhiều nhất?',['Điện áp','Dòng hàn','Cực tính','Cả a và b'],'MMA dùng nguồn DÒNG KHÔNG ĐỔI (đặc tính dốc): dòng gần như giữ nguyên, điện áp thay đổi theo chiều dài hồ quang.'),
M(1,'P2-10a. With reference to the previous question and the correct answer, what is the electrical characteristic referred to as for this process?',['Flat characteristic','Constant voltage','Constant current','Variable amperage'],2,'Theo câu trước, đặc tính điện của quá trình này gọi là gì?',['Đặc tính phẳng','Điện áp không đổi','Dòng không đổi','Dòng biến đổi'],'MMA, TIG, SAW dòng lớn (>1000 A) dùng nguồn dòng không đổi (constant current / drooping). MIG/MAG, FCAW, SAW <1000 A dùng điện áp không đổi (flat).'),
M(1,'P2-11. An undesirable property of aluminium oxide residue is that it:',['Creates problems when welding in position (vertical, horizontal, overhead).','It melts at a higher point than the aluminium','Forms a slag','Decreases weld pool fluidity.'],1,'Một tính chất bất lợi của lớp oxit nhôm là:',['Gây khó khi hàn các tư thế (đứng, ngang, trần)','Nóng chảy ở nhiệt độ cao hơn nhôm','Tạo thành xỉ','Làm giảm độ chảy loãng vũng hàn'],'Al₂O₃ nóng chảy ~2050 °C trong khi nhôm ~660 °C → nhôm chảy bên dưới mà lớp oxit chưa chảy → ngậm oxit, không ngấu. Phải phá oxit (cathodic cleaning).'),
M(1,'P2-11a. With reference to the previous question and the correct answer, how can this issue be overcome using the TIG process?',['Use alternating current','Use Direct current negative polarity','Use Direct current positive polarity','All options can be used for this purpose'],0,'Theo câu trước, khắc phục bằng hàn TIG như thế nào?',['Dùng dòng xoay chiều (AC)','Dùng DC cực âm','Dùng DC cực dương','Dùng phương án nào cũng được'],'AC: nửa chu kỳ điện cực dương phá oxit (làm sạch catot), nửa chu kỳ âm làm nguội vonfram và cho độ ngấu. DC+ làm sạch tốt nhất nhưng vonfram quá nóng nên thực tế dùng AC.'),
M(7,'P2-12. A welder qualified in the PG position would normally be qualified for welding:',['All diameters of pipe.','Welding positions PA, PC, PG, and PF.','In position PG only.','All pipe wall thickness.'],2,'Thợ hàn được chứng nhận ở tư thế PG thường được phép hàn:',['Mọi đường kính ống','Tư thế PA, PC, PG và PF','Chỉ tư thế PG','Mọi chiều dày thành ống'],'ISO 9606-1: hàn xuống (PG) chỉ phủ PG (và J-L045 với ống). Kỹ thuật hàn xuống khác hẳn nên không phủ tư thế khác. Đường kính và chiều dày có phạm vi riêng.'),
M(7,'P2-12a. With reference to the previous question and the correct answer, why would this be the case?',['With certain diameter of pipes all diameters are approved','The arc characteristics and technique are unique to this welding position','Pipe thickness are not covered with approval ranges','Certain welding positions are very similar'],1,'Theo câu trước, vì sao như vậy?',['Với một số đường kính ống thì mọi đường kính đều được chấp thuận','Đặc tính hồ quang và kỹ thuật là riêng cho tư thế này','Chiều dày ống không nằm trong phạm vi chấp thuận','Một số tư thế rất giống nhau'],'Hàn xuống dùng kỹ thuật riêng (tốc độ nhanh, que cellulosic, hồ quang đẩy xỉ) → không tương đương các tư thế khác.'),
M(4,'P2-13. A fabrication calls for the toes to be blended in by grinding. The most likely reason for this is to…',['Make the weld suitable for liquid (dye) penetrant inspection','Improve the fatigue life','Reduce residual stresses','Improve the general appearance of the welds'],1,'Hồ sơ chế tạo yêu cầu mài chuyển tiếp chân mối hàn. Lý do có khả năng nhất là…',['Để mối hàn phù hợp kiểm tra thẩm thấu','Tăng tuổi thọ mỏi','Giảm ứng suất dư','Cải thiện vẻ ngoài'],'Mài chân mối hàn loại bỏ góc chuyển tiếp sắc và khuyết tật nhỏ ở chân → giảm tập trung ứng suất → tăng tuổi thọ mỏi đáng kể.'),
M(4,'P2-13a. With reference to the previous question and the correct answer, this will reduce?',['Internal stresses','Stress raisers','Longitudinal stresses','Tensile stresses'],1,'Theo câu trước, việc này làm giảm?',['Ứng suất bên trong','Điểm tập trung ứng suất','Ứng suất dọc','Ứng suất kéo'],'Giảm "stress raiser" (điểm tập trung ứng suất) tại chân mối hàn. Mài chân không giảm ứng suất dư (cần PWHT).'),
M(8,'P2-14. A carbon equivalent of 0.48%:',['Is high for carbon steel and may require a preheat temperature over 100oC.','Is insignificant for carbon steel and preheat will not be required.','Is calculated from the heat-input formula.','Is not a consideration for determining preheating temperatures.'],0,'Đương lượng cacbon 0,48%:',['Cao với thép cacbon, có thể cần gia nhiệt trên 100 °C','Không đáng kể, không cần gia nhiệt','Tính từ công thức nhiệt lượng đưa vào','Không cần xét khi xác định nhiệt độ gia nhiệt'],'CE <0,4: thường không cần gia nhiệt; 0,4–0,5: cần gia nhiệt tùy chiều dày/hydro; >0,5: chắc chắn cần gia nhiệt, quy trình hydro thấp. 0,48 là cao với thép cacbon.'),
M(8,'P2-14a. With reference to the previous question, what could happen if pre heat was required but was not carried out?',['Possibility of martensite being formed','Possibility of hydrogen being formed','Possibility of solidification cracking','Possibility of lamellar tearing'],0,'Theo câu trước, nếu cần gia nhiệt mà không làm thì điều gì có thể xảy ra?',['Có thể hình thành martensite','Có thể sinh hydro','Có thể nứt kết tinh','Có thể rách lớp'],'Không gia nhiệt → nguội nhanh → martensite cứng giòn ở HAZ → nguy cơ nứt nguội hydro. Gia nhiệt không tạo/giảm "sinh hydro" mà giúp hydro thoát.'),
M(2,'P2-15. Which of the following statements is true?',['The core wire of an MMA electrode has a lower melting point than the flux.','Basic electrodes are preferred when welding is carried out in situations where porosity free welds are specified.','Rutile electrodes always contain a large proportion of iron powder.','Cellulose electrodes may deposit in excess of 90ml of hydrogen per 100g of weld metal.'],3,'Phát biểu nào đúng?',['Lõi que MMA có nhiệt độ chảy thấp hơn thuốc bọc','Que basic được ưu tiên khi yêu cầu mối hàn không rỗ','Que rutile luôn chứa nhiều bột sắt','Que cellulosic có thể cho trên 90 ml hydro/100 g kim loại đắp'],'Slide Handout: que cellulosic có hàm lượng hydro 80–90 ml/100 g → "có thể vượt 90" là phát biểu đề TWI chọn. Que basic lại dễ rỗ đầu đường hàn nếu hồ quang dài; rutile không "luôn" có bột sắt.','(†) Sách WIS5 chỉ ghi "high level of hydrogen"; slide 80–90 ml. Câu hỏi nối tiếp (15a: "lực hồ quang mạnh") khẳng định đáp án là que cellulosic.'),
M(2,'P2-15a. With reference to the previous question and the correct answer, what’s unique about these electrodes?',['They are not hygroscopic','They have a high recovery rate','They have a stronger arc force','The core is made from a high grade steel'],2,'Theo câu trước, điểm đặc biệt của loại que này là gì?',['Không hút ẩm','Hệ số đắp cao','Lực hồ quang mạnh hơn','Lõi làm bằng thép chất lượng cao'],'Cellulose cháy sinh nhiều khí (H₂, CO) → điện áp hồ quang cao, hồ quang "đào" sâu, lực mạnh → ngấu sâu, hàn xuống (stove pipe). Que cellulosic CẦN có ẩm trong thuốc, không được sấy khô.'),
/* ----- Paper 2 điền khuyết ----- */
M(6,'P2-27. Using the radiographic NDT method of inspection using the double wall double image exposure, both the film and source goes ________.',['Inside','outside','both sides','all around'],1,'Chụp phóng xạ xuyên hai thành – hai ảnh (DWDI): cả phim và nguồn đặt ___.',['bên trong','bên ngoài','hai phía','xung quanh'],'DWDI (ống nhỏ ≤ ~100 mm): nguồn và phim đều NGOÀI ống, chùm tia lệch góc để ảnh hai thành tạo hình elip.'),
M(7,'P2-28. A welder qualification certificate _______ record the tests conducted on the specimen.',['Does not','does','occasionally','in certain circumstances'],1,'Chứng chỉ thợ hàn ___ ghi lại các phép thử đã thực hiện trên mẫu.',['không','có','thỉnh thoảng','trong một số trường hợp'],'Chứng chỉ ISO 9606 có mục "Type of test" ghi các phép thử (ngoại quan, RT, uốn, bẻ gãy, macro) và kết quả.'),
M(16,'P2-29. Carbon arc gouging can cut _________.',['only stainless steel and aluminium','only carbon steel and stainless steel','only non-ferrous materials','ferrous and non-ferrous materials'],3,'Dũi hồ quang điện cực than (carbon arc gouging) có thể cắt ___.',['chỉ thép không gỉ và nhôm','chỉ thép cacbon và thép không gỉ','chỉ kim loại màu','cả kim loại đen và kim loại màu'],'Dũi hồ quang khí nén là làm chảy rồi thổi đi (không dựa vào phản ứng oxy hóa như cắt oxy-gas) → dùng được cho kim loại đen lẫn kim loại màu.'),
M(9,'P2-30. On a CMn steel butt weld ________ will require a decrease in pre heat temperature.',['increasing weld speed','increasing gas flow rate','increasing heat input','decreasing heat input'],2,'Với mối giáp mối thép C-Mn, ___ sẽ cho phép giảm nhiệt độ gia nhiệt.',['tăng tốc độ hàn','tăng lưu lượng khí','tăng nhiệt lượng đưa vào','giảm nhiệt lượng đưa vào'],'Heat input cao → nguội chậm → ít martensite, hydro có thời gian thoát → cần ít gia nhiệt hơn (EN 1011-2).'),
M(9,'P2-31. On a CMn steel butt weld, changing from a stringer to a weave technique will require_____.',['More pre heat','less pre heat','more amperage','a change in polarity'],1,'Mối giáp mối thép C-Mn, chuyển từ kỹ thuật kéo thẳng (stringer) sang dao động (weave) sẽ cần ___.',['gia nhiệt nhiều hơn','gia nhiệt ít hơn','dòng hàn lớn hơn','đổi cực tính'],'Dao động → tiến chậm → heat input tăng → cần ít gia nhiệt hơn.'),
M(9,'P2-32. Changing the joint configuration from a tee fillet to a butt joint will require _____.',['More pre heat','a change in polarity','less pre heat','an increase in welding speed'],2,'Đổi cấu hình mối nối từ mối góc chữ T sang mối giáp mối sẽ cần ___.',['gia nhiệt nhiều hơn','đổi cực tính','gia nhiệt ít hơn','tăng tốc độ hàn'],'Mối T có 3 đường tản nhiệt (chiều dày tổng hợp lớn) → nguội nhanh hơn. Mối giáp mối chỉ 2 đường tản nhiệt → nguội chậm hơn → cần ít gia nhiệt hơn.'),
M(8,'P2-33. To prevent solidification cracking ________ form between the grains to maintain cohesion.',['Iron sulphides','manganese sulphides','magnesium sulphides','aluminium sulphides'],1,'Để chống nứt kết tinh, ___ hình thành giữa các hạt để giữ liên kết.',['Sunfua sắt','Sunfua mangan','Sunfua magie','Sunfua nhôm'],'Mn kết hợp S thành MnS điểm chảy cao, dạng hạt cầu, không tạo màng lỏng. FeS điểm chảy thấp tạo màng lỏng giữa hạt → nứt kết tinh.'),
M(8,'P2-34. To measure a materials susceptibility to Lamellar tearing, _________ is measure after a STRA test.',['UTS','yield','reduction in area','proof stress'],2,'Để đo độ nhạy rách lớp, sau thử STRA người ta đo ___.',['Giới hạn bền','Giới hạn chảy','Độ thắt tiết diện','Giới hạn chảy quy ước'],'STRA = Short Transverse Reduction of Area: thử kéo theo chiều dày, đo % độ thắt tiết diện. STRA >20% (thép Z) là chống rách lớp tốt.'),
M(8,'P2-35. In a stabilised stainless steel, the element _________ helps prevent chromium carbides forming which leads to weld decay.',['Chromium','carbon','titanium','nickel'],2,'Trong thép không gỉ ổn định hóa, nguyên tố ___ giúp ngăn tạo cacbit crom dẫn tới weld decay.',['Crom','Cacbon','Titan','Niken'],'Ti (mác 321) hoặc Nb (mác 347) có ái lực với C mạnh hơn Cr → "giữ" cacbon thành cacbit Ti/Nb → Cr còn nguyên chống ăn mòn.'),
M(17,'P2-36. Pre heat on a CMn steel repair would normally need to be _______.',['higher than the original weld','lower than the original weld','not required','the same as the original weld'],0,'Gia nhiệt khi hàn sửa chữa thép C-Mn thường phải ___.',['cao hơn mối hàn gốc','thấp hơn mối hàn gốc','không cần','bằng mối hàn gốc'],'Rãnh sửa chữa ngắn, bị kìm hãm mạnh, khối thép xung quanh tản nhiệt nhanh → nguội nhanh hơn mối gốc → thường cần gia nhiệt CAO hơn (thường +50 °C).'),
/* ===================== PAPER 3 ===================== */
M(2,'P3-1. A typical temperature range for baking basic coated electrodes is?',['150 - 200°C','200 - 250°C','300 - 350°C','400 - 450°C'],2,'Khoảng nhiệt độ sấy điển hình cho que bọc thuốc basic là?',['150–200 °C','200–250 °C','300–350 °C','400–450 °C'],'Sấy que basic 300–350 °C khoảng 1 giờ, rồi giữ trong tủ giữ nhiệt ~150 °C, bình mang theo (quiver) ~70–80 °C.'),
M(2,'P3-1a. With reference to the previous question, why does this have to be done?',['These electrodes are hygroscopic','It allows equalization of the alloying elements','It helps bonds the core to the flux','It stop the flux from flaking off'],0,'Theo câu trước, vì sao phải sấy?',['Que này hút ẩm','Để cân bằng nguyên tố hợp kim','Để gắn lõi với thuốc','Để thuốc không bong'],'Thuốc basic hút ẩm (hygroscopic); ẩm = nguồn hydro → nứt nguội. Sấy để đạt mức hydro thấp (H5).'),
M(1,'P3-2. If welding travel speed is doubled but the current and voltage remain the same, the heat input will be?',['Reduced by 50%','Increased by a factor of two','About the same','Reduced by approximately 25%'],0,'Nếu tốc độ hàn tăng gấp đôi, dòng và áp giữ nguyên, nhiệt lượng đưa vào sẽ?',['Giảm 50%','Tăng gấp hai','Gần như không đổi','Giảm khoảng 25%'],'HI = k·U·I / v: tốc độ v ở mẫu số → v gấp đôi thì HI giảm một nửa.'),
M(8,'P3-2a. With reference to the previous question, what could be the possible outcome of this?',['Increased hardness','Increased toughness','Improved weldability','The material would be sensitised'],0,'Theo câu trước, hậu quả có thể là gì?',['Tăng độ cứng','Tăng độ dai','Cải thiện tính hàn','Vật liệu bị nhạy hóa'],'HI thấp → nguội nhanh → HAZ cứng hơn (nguy cơ martensite, nứt hydro).','(†) HI thấp cũng có thể tăng độ dai do hạt mịn; nhưng hậu quả đáng lo và đề hướng tới là tăng độ cứng.'),
M(2,'P3-3. What type of submerged arc welding flux would be susceptible to moisture pickup?',['Neutral','Agglomerated','Fused','All about the same'],1,'Loại thuốc hàn SAW nào dễ hút ẩm?',['Trung tính','Kết tụ (agglomerated)','Nung chảy (fused)','Như nhau'],'Thuốc kết tụ (thường basic) liên kết bằng chất kết dính ở nhiệt độ thấp, xốp → hút ẩm; phải sấy. Thuốc nung chảy dạng thủy tinh, không hút ẩm.'),
M(2,'P3-3a. With reference to the previous question, why is this the case?',['It’s because they are very dry','It’s because they are hygroscopic','It’s because they are droscopic','It’s because they are endoscopic'],1,'Theo câu trước, vì sao?',['Vì chúng rất khô','Vì chúng hút ẩm (hygroscopic)','(từ sai)','(từ sai — nội soi)'],'Hygroscopic = có tính hút ẩm từ không khí.'),
M(8,'P3-4. A large grain size in the HAZ of a CMn steel weld joint may have?',['Low ductility','Low toughness','High toughness','High tensile strength'],1,'Hạt lớn ở HAZ của mối hàn thép C-Mn có thể gây?',['Độ dẻo thấp','Độ dai thấp','Độ dai cao','Độ bền kéo cao'],'Hạt thô → độ dai (năng lượng va đập Charpy) giảm. Hạt mịn → dai cao.'),
M(8,'P3-4a. With reference to the previous question and the correct answer, what would have caused this condition?',['Welding in the horizontal position','Too high a pre heat','Multi pass welding','Welding speed too slow'],3,'Theo câu trước, nguyên nhân gây ra tình trạng này?',['Hàn tư thế ngang','Gia nhiệt quá cao','Hàn nhiều lớp','Tốc độ hàn quá chậm'],'Tốc độ chậm → heat input cao → HAZ ở nhiệt độ cao lâu → hạt lớn. Hàn nhiều lớp lại có tác dụng ram, làm mịn hạt.','(†) Gia nhiệt quá cao cũng góp phần, nhưng nguyên nhân chính TWI nêu là heat input cao (tốc độ chậm).'),
M(10,'P3-5. The property of a material which has the greatest influence on welding distortion is it’s?',['Yield strength','Material thickness','Elastic modulus','Coefficient of thermal conductivity'],3,'Tính chất vật liệu ảnh hưởng LỚN NHẤT đến biến dạng hàn là?',['Giới hạn chảy','Chiều dày vật liệu','Mô đun đàn hồi','Hệ số dẫn nhiệt'],'WIS5 19.4.1: tính chất vật liệu ảnh hưởng biến dạng là hệ số GIÃN NỞ nhiệt và độ DẪN NHIỆT; giới hạn chảy và mô đun Young ảnh hưởng ít hơn. Chiều dày không phải tính chất vật liệu.','(†) Đề không có "hệ số giãn nở" (yếu tố số 1); trong các phương án, dẫn nhiệt là đúng theo sách.'),
M(10,'P3-5a. With reference to the previous question and the correct answer, why is this the case?',['Thick materials rarely distort','The more elastic they are the more they distort','Low yield materials will distort more','High yield materials will distort more'],2,'Theo câu trước, vì sao?',['Vật liệu dày ít biến dạng','Càng đàn hồi càng biến dạng','Vật liệu giới hạn chảy thấp biến dạng nhiều hơn','Vật liệu giới hạn chảy cao biến dạng nhiều hơn'],'Ứng suất co ngót vượt giới hạn chảy thì sinh biến dạng dẻo vĩnh viễn; giới hạn chảy càng thấp càng dễ biến dạng dẻo → biến dạng nhiều.','(†) Không phương án nào nói về dẫn nhiệt; đây là ý đúng duy nhất trong các phương án.'),
M(8,'P3-6. Which of the following is associated with SAW more often than it is with MMA welds?',['Hydrogen cracking in the weld metal','Solidification cracking in the weld metal','Reheat cracking during PWHT','Lamellar tearing'],1,'Hiện tượng nào gặp ở SAW nhiều hơn MMA?',['Nứt hydro trong kim loại mối hàn','Nứt kết tinh trong kim loại mối hàn','Nứt khi ram lại trong PWHT','Rách lớp'],'SAW ngấu sâu, độ pha loãng cao (kéo S, P từ kim loại cơ bản vào) và đường hàn sâu hẹp (tỉ lệ sâu/rộng >2) → nứt kết tinh ở tâm mối hàn.'),
M(8,'P3-6a. With reference to the previous question and the correct answer, why is this the case?',['Low dilution process','High dilution process','Contaminated flux','Low heat input process'],1,'Theo câu trước, vì sao?',['Quá trình pha loãng thấp','Quá trình pha loãng cao','Thuốc bẩn','Quá trình nhiệt thấp'],'Pha loãng cao → nhiều kim loại cơ bản (có S, P) đi vào mối hàn.'),
M(4,'P3-7. EN ISO 5817 (Level C) specifies that the limit for the diameter (D) of a single pore in a weld is? D equal to or less than 0.3s, but maximum 4mm where s = material thickness. For which of the following situations is the pore acceptable?',['S = 20mm, measured pore diameter = 5mm','S = 15mm, measured pore diameter = 4.5mm','S = 10mm, measured pore diameter = 3mm','S = 10mm, measured pore diameter = 3.5mm'],2,'EN ISO 5817 (mức C) giới hạn đường kính rỗ đơn D ≤ 0,3s nhưng tối đa 4 mm (s = chiều dày). Trường hợp nào rỗ được chấp nhận?',['s = 20, rỗ 5 mm','s = 15, rỗ 4,5 mm','s = 10, rỗ 3 mm','s = 10, rỗ 3,5 mm'],'a: 0,3×20 = 6 → bị chặn 4 → 5 >4 loại. b: 4,5 → chặn 4 → 4,5 loại. c: 0,3×10 = 3 → 3 ≤ 3 ĐẠT. d: 3,5 > 3 loại. Luôn áp dụng "cái nhỏ hơn" giữa 0,3s và 4 mm.'),
M(4,'P3-7a. With reference to the previous question, what could be the possible cause of these pores?',['MAG welding C Mn steel with a gas flow rate of 18 litres per minute, voltage 29, amperage 160 in the vertical up position.','MAG welding C Mn steel with a gas flow rate of 18 litres per minute, voltage 20, amperage 120 in the vertical up position.','MAG welding C Mn steel with a gas flow rate of 15 litres per minute, voltage 18, amperage 100 in the vertical up position.','MAG welding C Mn steel with a gas flow rate of 15 litres per minute, voltage 16, amperage 90 in the vertical up position.'],0,'Theo câu trước, nguyên nhân có thể của rỗ là?',['MAG thép C-Mn, khí 18 l/phút, 29 V, 160 A, hàn đứng lên','MAG, khí 18 l/phút, 20 V, 120 A, hàn đứng lên','MAG, khí 15 l/phút, 18 V, 100 A, hàn đứng lên','MAG, khí 15 l/phút, 16 V, 90 A, hàn đứng lên'],'Lưu lượng khí cả 4 đều bình thường. 29 V với chỉ 160 A là điện áp QUÁ CAO → hồ quang dài, khí bảo vệ kém → rỗ. Các bộ còn lại có áp/dòng cân đối cho chế độ dip hàn đứng.'),
M(9,'P3-8. Typical temperatures used for normalising a C Mn steel plate are?',['600 - 650°c','1000 - 1100°c','700 - 800°c','880 - 920°c'],3,'Nhiệt độ thường hóa điển hình cho tấm thép C-Mn là?',['600–650 °C','1000–1100 °C','700–800 °C','880–920 °C'],'Thường hóa: nung trên điểm tới hạn trên (~900 °C, austenit hóa) rồi nguội trong không khí tĩnh. 600–650 là PWHT/ram; 1000–1100 là dung thể hóa inox.'),
M(9,'P3-8a. With reference to the previous question, what actually does normalising do?',['Softens the material making it easier to from','Hardens the material, ideal for certain applications','Produces a fine grain structure','Produces a coarse grain structure'],2,'Theo câu trước, thường hóa thực chất làm gì?',['Làm mềm vật liệu cho dễ tạo hình','Làm cứng vật liệu','Tạo tổ chức hạt mịn','Tạo tổ chức hạt thô'],'Thường hóa làm mịn hạt → tăng cả độ bền và độ dai. Làm mềm để gia công là ủ (annealing).'),
M(1,'P3-9. For GMAW the burn off rate of the wire is directly related to?',['Sick out length','Wire feed speed','Arc voltage','Travel speed'],1,'Với GMAW, tốc độ chảy dây (burn-off rate) liên quan trực tiếp tới?',['Tầm với điện cực','Tốc độ cấp dây','Điện áp hồ quang','Tốc độ hàn'],'Nguồn điện áp không đổi tự điều chỉnh: dây chảy đúng bằng tốc độ cấp dây; tăng tốc độ cấp dây = tăng dòng = tăng tốc độ chảy.'),
M(1,'P3-9a. With reference to the previous question, how is this parameter measured?',['Volts','Inductance','Amps','Resistance'],2,'Theo câu trước, thông số này đo bằng gì?',['Vôn','Điện cảm','Ampe','Điện trở'],'Tốc độ cấp dây quyết định DÒNG HÀN → đọc bằng ampe trên máy (tốc độ cấp dây bản thân đo bằng m/phút).'),
M(8,'P3-10. If arc strikes are found on carbon steel (carbon equivalent of 0.5%), what undesirable grain structure may be present?',['Pearlite.','Martensite.','Ferrite.','All of the above are undesirable grain structures in constructional steels.'],1,'Nếu thấy vết mồi hồ quang trên thép cacbon (CE 0,5%), tổ chức hạt bất lợi nào có thể có?',['Peclit','Martensite','Ferit','Tất cả đều bất lợi trong thép kết cấu'],'Vết mồi nguội cực nhanh, CE 0,5 dễ tôi → martensite cứng giòn. Ferit + peclit là tổ chức bình thường của thép kết cấu.'),
M(8,'P3-10a. With reference to the previous question, what features does this grain structure have?',['A very soft and ductile structure.','Hard and unstable structure','Good impact properties but poor tensile properties','Good tensile properties because of its ductility'],1,'Theo câu trước, tổ chức này có đặc điểm gì?',['Rất mềm và dẻo','Cứng và không ổn định','Va đập tốt nhưng bền kéo kém','Bền kéo tốt nhờ dẻo'],'Martensite: rất cứng, giòn, ứng suất nội lớn, là pha không ổn định (giả ổn định) — dễ nứt.'),
M(5,'P3-11. Which of the following units is used to measure the energy absorbed in charpy impact testing.',['Newtons','Pascals','Joules','Mega Pascals'],2,'Đơn vị đo năng lượng hấp thụ trong thử va đập Charpy là?',['Niutơn','Pascal','Jun (J)','Megapascal'],'Năng lượng va đập đo bằng Jun (J). N/mm² = MPa là đơn vị ứng suất.'),
M(5,'P3-11a. With reference to the previous question, what does this test tell us?',['Its toughness at a given temperature','Its yield and UTS values','Its proof stress value','Its resistance to cyclic loading'],0,'Theo câu trước, thử nghiệm này cho biết gì?',['Độ dai ở một nhiệt độ xác định','Giới hạn chảy và bền kéo','Giới hạn chảy quy ước','Khả năng chịu tải chu kỳ (mỏi)'],'Charpy đo ĐỘ DAI (khả năng hấp thụ năng lượng khi có khía) ở nhiệt độ thử quy định; thường thử 3 mẫu mỗi nhiệt độ.'),
M(2,'P3-12. What does the 70 represent on an E7018 AWS A5.1 classified electrode?',['70 N/mm2 minimum UTS.','70N/mm2 minimum impact strength.','70,000 p.s.i. minimum UTS.','70,000 p.s.i. minimum yield strength.'],2,'Số 70 trên que E7018 theo AWS A5.1 nghĩa là gì?',['UTS tối thiểu 70 N/mm²','Độ bền va đập 70 N/mm²','UTS tối thiểu 70 000 psi','Giới hạn chảy tối thiểu 70 000 psi'],'AWS: hai số đầu = giới hạn BỀN KÉO tối thiểu ×1000 psi (70 ksi ≈ 480 N/mm²). Khác ISO 2560-A (E 42…): số là giới hạn CHẢY N/mm².'),
M(2,'P3-12a. With reference to the previous question, what type of flux coating does this electrode have?',['Basic','Rutile','Cellulosic','Iron powder'],0,'Theo câu trước, que này có thuốc bọc loại gì?',['Basic','Rutile','Cellulosic','Bột sắt'],'Số cuối "8" = basic + bột sắt, hydro thấp, DC+ hoặc AC. 0–1 cellulosic; 2–3–4 rutile; 5–6–7–8 basic.'),
M(7,'P3-13. Which of the following tests would you not expect to be carried out on a welder qualification test?',['Radiography.','Tensile test.','Macro.','Bend test.'],1,'Phép thử nào KHÔNG được thực hiện khi chứng nhận thợ hàn?',['Chụp phóng xạ','Thử kéo','Macro','Thử uốn'],'Chứng nhận thợ hàn chỉ kiểm tra CHẤT LƯỢNG LÀNH LẶN (ngoại quan, RT, uốn, bẻ gãy, macro). Thử kéo đo cơ tính → dùng cho chứng nhận quy trình (PQR).'),
M(5,'P3-13a. With reference to the previous question, which of the tests is considered a quantitative test?',['Bend test','Macro','Radiography','Tensile test'],3,'Theo câu trước, phép thử nào là định lượng?',['Uốn','Macro','Chụp phóng xạ','Kéo'],'Thử kéo cho con số (N/mm², %) → định lượng. Uốn, macro → định tính.'),
M(6,'P3-14. Which material would be the least effective for DPI?',['316 L stainless steel','Carbon manganese steel','Cast Iron.','Both a and c.'],2,'Vật liệu nào kém hiệu quả nhất khi kiểm tra thẩm thấu (DPI)?',['Thép không gỉ 316L','Thép C-Mn','Gang','Cả a và c'],'Gang xốp, nhiều lỗ → chất thẩm thấu đọng khắp nơi → nền nhiễu, chỉ thị giả. PT dùng tốt cho 316L (đây lại là vật liệu không dùng được MT).'),
M(6,'P3-14a. with reference to the previous question, the main reason why this would be the case is that the material is?',['Non magnetic','Porous','Carbon content too high','Thermal conductivity too low'],1,'Theo câu trước, lý do chính là vật liệu:',['Không nhiễm từ','Xốp','Cacbon quá cao','Dẫn nhiệt quá thấp'],'PT cần bề mặt không xốp; vật liệu xốp giữ chất thẩm thấu → không phân biệt được khuyết tật.'),
M(1,'P3-15. Globular transfer is used in which welding process?',['TIG','MMA/SMAW','GMAW/MAG','SAW'],2,'Chuyển dịch giọt lớn (globular) dùng trong quá trình nào?',['TIG','MMA','GMAW/MAG','SAW'],'Bốn chế độ chuyển dịch của MIG/MAG: ngắn mạch (dip), giọt lớn (globular), phun (spray), xung (pulse).'),
M(1,'P3-15a. With reference to the previous question and the correct answer, what current is used for this type of transfer mode?',['AC','DC and AC','DC-','DC+'],3,'Theo câu trước, chế độ chuyển dịch này dùng dòng gì?',['AC','DC và AC','DC−','DC+'],'MIG/MAG dùng DC+ (điện cực dương) cho mọi chế độ chuyển dịch; một số dây FCAW tự bảo vệ dùng DC−.'),
/* ----- Paper 3 điền khuyết ----- */
M(10,'P3-26. Welding around the _______ will reduce the level of distortion.',['The ends','the flange','end axis','neutral axis'],3,'Hàn quanh ___ sẽ giảm mức biến dạng.',['hai đầu','mặt bích','trục đầu mút','trục trung hòa'],'Đặt và hàn cân đối quanh TRỤC TRUNG HÒA → mô men co ngót hai phía triệt tiêu nhau → ít biến dạng (WIS5 19.5).'),
M(9,'P3-27. Annealing is done to ______ the material.',['Soften','harden','improve tensile strength','improve toughness'],0,'Ủ (annealing) được thực hiện để ___ vật liệu.',['làm mềm','làm cứng','tăng bền kéo','tăng độ dai'],'Ủ ~900–920 °C nguội trong lò → vật liệu rất mềm, dẻo, dễ gia công/tạo hình; độ bền và độ dai giảm.'),
M(9,'P3-28. Pre heat measurement on materials above 50mm thick are done _______ from the bevel face.',['25mm','30mm','55mm','75mm'],3,'Đo nhiệt độ gia nhiệt với vật liệu dày trên 50 mm được thực hiện cách mặt vát ___.',['25 mm','30 mm','55 mm','75 mm'],'t ≤ 50 mm: đo cách mép 4t (tối đa 50 mm); t > 50 mm: tối thiểu 75 mm (EN ISO 13916). Giữ 2 phút cho mỗi 25 mm chiều dày.'),
M(2,'P3-29. The electrode designation E8018-B2 to AWS 5.5 would mean the electrode is a ______ type.',['Rutile iron powder','basic','cellulosic','rutile'],1,'Que E8018-B2 theo AWS A5.5 là loại ___.',['rutile bột sắt','basic','cellulosic','rutile'],'Chữ số cuối 8 → basic (bột sắt, hydro thấp). B2 = hợp kim 1¼Cr–½Mo (thép chịu nhiệt).'),
M(2,'P3-30. In MMA welding, cellulosic electrodes are designed to be used in this welding position ________ also known as stoving.',['PG','PF','PC','PD'],0,'Trong hàn MMA, que cellulosic được thiết kế cho tư thế ___ còn gọi là hàn "stove pipe".',['PG (đứng hàn xuống)','PF (đứng hàn lên)','PC (ngang)','PD (trần ngang)'],'Stove pipe: hàn ống đường dài theo chiều đi XUỐNG (PG) bằng que cellulosic, ngấu sâu, nhanh.'),
M(1,'P3-31. A _________ is deployed with the Tig welding process to prevent crater cracking.',['Pre gas supply','slope out current','post gas supply','slope in current'],1,'Trong hàn TIG dùng ___ để chống nứt hõm cuối.',['Cấp khí trước','Giảm dòng cuối (slope-out)','Cấp khí sau','Tăng dòng đầu (slope-in)'],'Slope-out giảm dòng dần ở cuối, vũng hàn nhỏ lại → không có lõm co, không nứt hõm cuối.'),
M(1,'P3-32. When welding CMn steel with the Tig welding process, the tungsten electrode should have a _______ preparation.',['Long taper with a point','short taper with no point','short taper rounded at the end','no preparation'],0,'Khi hàn TIG thép C-Mn, điện cực vonfram cần được chuẩn bị dạng ___.',['vát côn dài có mũi nhọn','côn ngắn không mũi nhọn','côn ngắn bo tròn đầu','không chuẩn bị'],'Thép hàn bằng DC− → mài vonfram côn nhọn, chiều dài côn ~2–2,5 lần đường kính (slide Handout). Đầu bo tròn (balled) dùng cho AC (nhôm).'),
M(1,'P3-33. Positional welding can be done in spray transfer when using _________.',['Solid wires','C0₂','flux cored wires','mixed gases'],2,'Có thể hàn các tư thế ở chế độ phun (spray) khi dùng ___.',['dây đặc','CO₂','dây lõi thuốc','khí hỗn hợp'],'Spray với dây đặc chỉ hàn được PA/PB (vũng hàn lớn, lỏng). Dây lõi thuốc rutile có xỉ đỡ vũng hàn → spray hàn được mọi tư thế. CO₂ không duy trì được spray.'),
M(1,'P3-34. Flux cored wires have a higher deposition rate because _________.',['of the flux','of higher resistance','of lower resistance','of no resistance'],1,'Dây lõi thuốc có tốc độ đắp cao hơn vì ___.',['có thuốc','điện trở cao hơn','điện trở thấp hơn','không có điện trở'],'Dòng chỉ đi qua vỏ kim loại mỏng → mật độ dòng và nhiệt điện trở (I²R) trong phần dây nhô ra cao → dây chảy nhanh hơn → tốc độ đắp cao.'),
M(1,'P3-35. In the submerged arc welding process, if _______ is increased penetration will decrease.',['Wire feed','inductance','voltage','gas flow'],2,'Trong hàn SAW, nếu tăng ___ thì độ ngấu sẽ giảm.',['tốc độ cấp dây','điện cảm','điện áp','lưu lượng khí'],'Tăng điện áp → hồ quang dài, đường hàn rộng phẳng, ngấu nông hơn. Tăng cấp dây = tăng dòng → ngấu sâu hơn. SAW không dùng khí.')
]};

/* ============== KÉO–THẢ (CÓ THỂ NHIỀU ĐÁP ÁN) ============== */
window.THI_HWDD = {id:'hwdd', icon:'🧲', vi:'Homework TWI — kéo–thả nhiều đáp án (30 câu)', en:'TWI Homework drag & drop', type:'ms', items:[
M(5,'P1-16. A macro examination would be considered?',['a quantitative test','a hardness test','a detailed test','a qualitative test','a destructive test'],[3,4],'Kiểm tra macro được xem là?',['phép thử định lượng','phép thử độ cứng','phép thử chi tiết','phép thử định tính','phép thử phá hủy'],'Macro: cắt mẫu ngang, mài, tẩm thực, quan sát ×5 → PHÁ HỦY và ĐỊNH TÍNH. Độ cứng là phép khác (dù có thể làm trên cùng mẫu).'),
M(5,'P1-17. A Charpy impact specimen, may show which of the following?',['Brittle failure','cyclic failure','solidification failure','ductile failure','plastic failure','elastic failure'],[0,3],'Mẫu va đập Charpy có thể thể hiện kiểu phá hủy nào?',['Phá hủy giòn','phá hủy chu kỳ','phá hủy kết tinh','phá hủy dẻo','phá hủy dẻo-plastic','phá hủy đàn hồi'],'Mặt gãy Charpy: GIÒN (phẳng, sáng, hạt tinh thể, vết chevron, ít biến dạng) hoặc DẺO (xám, xơ, môi cắt, thắt tiết diện). Chu kỳ = mỏi.'),
M(5,'P1-18. In bend testing, which of the following is generally NOT done?',['Excess weld metal removed','10% radius produced on the longer lengths of the sample','excess weld metal not removed','diameter of former 4t of the specimen thickness','bend angle up to 180°'],[2],'Khi thử uốn, việc nào thường KHÔNG làm?',['Bỏ kim loại đắp dư','Bo tròn 10% cạnh dọc mẫu','Không bỏ kim loại đắp dư','Đường kính chày uốn = 4t','Góc uốn tới 180°'],'Mẫu uốn phải mài phẳng kim loại đắp dư (để ứng suất đều), bo cạnh dọc, chày 4t, uốn đến 180°. Để nguyên đắp dư là KHÔNG làm.','(†) Bo cạnh theo ISO 5173 là r ≤ 0,2t (tối đa 3 mm); "10%" là cách đề diễn đạt.'),
M(5,'P1-19. A tensile test was conducted on a specimen 200mm in length. After completion, the specimen measured 250mm in length. What is the percentage elongation?',['20%','25%','30%','15%','18%','16%'],[1],'Mẫu kéo dài 200 mm, sau thử dài 250 mm. Độ giãn dài phần trăm?',['20%','25%','30%','15%','18%','16%'],'A% = (250 − 200)/200 × 100 = 25%. Nhớ chia cho chiều dài BAN ĐẦU.'),
M(6,'P1-20. When using MPI, the defects are detected at?',['180° to the magnetic force','directly between the poles','at right angles to the magnetic force','50mm from the poles'],[1,2],'Khi kiểm tra bột từ (MPI), khuyết tật được phát hiện ở đâu?',['180° so với từ trường','ngay giữa hai cực','vuông góc với từ trường','cách cực 50 mm'],'Từ trường rò mạnh nhất khi khuyết tật VUÔNG GÓC đường sức (WIS5 5.4); vùng kiểm tra hiệu quả nằm GIỮA hai cực gông từ. Vì vậy phải từ hóa hai hướng vuông góc nhau.','(†) Một số đáp án chỉ chọn "vuông góc"; "giữa hai cực" cũng đúng với gông từ.'),
M(0,'P1-21. Which of the following would a welding inspector be required to do after welding?',['Check PWHT','check pre heat temperature','arrange NDT, sentence the weld','check dimensions','complete report','check material certificates'],[0,2,3,4],'Thanh tra hàn phải làm gì SAU khi hàn?',['Kiểm tra PWHT','kiểm tra nhiệt độ gia nhiệt','bố trí NDT, kết luận mối hàn','kiểm tra kích thước','hoàn thành báo cáo','kiểm tra chứng chỉ vật liệu'],'Sau hàn: nhận dạng mối, ngoại quan, kích thước, NDT, PWHT, sửa chữa, áp lực, hồ sơ báo cáo. Gia nhiệt là trước/trong khi hàn; chứng chỉ vật liệu là trước khi hàn.'),
M(15,'P1-22. What would be the weld area volume for a 6mm equal leg length fillet weld?',['10mm²','18mm²','16mm²','14mm²','12mm²','15mm²'],[1],'Diện tích tiết diện mối hàn góc cạnh đều 6 mm là bao nhiêu?',['10 mm²','18 mm²','16 mm²','14 mm²','12 mm²','15 mm²'],'Tam giác vuông cân: 6 × 6 / 2 = 18 mm² (không tính đắp dư).'),
M(1,'P1-23. Which of the following are used to calculate heat input?',['Travel speed','electrode size','polarity','voltage','gas flow rate','Thermal Efficiency Factor','amperage'],[0,3,5,6],'Những đại lượng nào dùng để tính nhiệt lượng đưa vào?',['Tốc độ hàn','cỡ que','cực tính','điện áp','lưu lượng khí','hệ số hiệu suất nhiệt','dòng hàn'],'HI = k × U × I × 60 / (v × 1000) kJ/mm: điện áp, dòng, tốc độ hàn, hệ số k (SAW 1,0; MMA/MIG/MAG/FCAW 0,8; TIG 0,6).'),
M(1,'P1-24. Which of the following materials can be welded with the SAW process?',['HSLA steels','stainless steel','aluminium','Duplex','CMn steels','copper alloys'],[0,1,3,4],'Vật liệu nào hàn được bằng SAW?',['Thép HSLA','thép không gỉ','nhôm','Duplex','thép C-Mn','hợp kim đồng'],'SAW dùng cho thép C-Mn, thép hợp kim thấp/HSLA, thép chịu nhiệt, không gỉ, duplex, hợp kim niken. Không dùng cho nhôm, đồng.'),
M(8,'P2-16. What precautions can be taken to avoid hydrogen cracking?',['Pre set joint','peen the weld after completion','ensure good fit up','avoid poor weld profiles','use a weave technique','ensure workshop temperature is above 20°c'],[2,3],'Biện pháp nào giúp tránh nứt hydro?',['Đặt trước mối nối','búa gõ mối hàn sau khi xong','bảo đảm lắp ghép tốt','tránh biên dạng mối hàn xấu','dùng kỹ thuật dao động','giữ xưởng trên 20 °C'],'Giảm ỨNG SUẤT: lắp ghép tốt, biên dạng tốt (không tập trung ứng suất). Cùng với gia nhiệt, quy trình hydro thấp, PWHT/giữ nhiệt sau hàn. Đặt trước là chống biến dạng; nhiệt độ xưởng không phải là gia nhiệt.'),
M(8,'P2-17. What level of hydrogen in ml is considered as a good precaution against HICC?',['5ml','8ml','10ml','12ml','15ml','20ml'],[0],'Hàm lượng hydro bao nhiêu ml được xem là biện pháp tốt chống HICC?',['5 ml','8 ml','10 ml','12 ml','15 ml','20 ml'],'H5 (≤5 ml/100 g) là "hydro thấp" của que basic sấy đúng, MIG, TIG. Ngưỡng nguy hiểm >15 ml/100 g.'),
M(8,'P2-18. Which of the following welding processes would be less likely to produce HICC?',['SAW','MAG','MMA','FCAW','MIG','TIG'],[1,4,5],'Quá trình nào ít có khả năng gây HICC?',['SAW','MAG','MMA','FCAW','MIG','TIG'],'Slide Handout: TIG <3 ml; MIG/MAG (dây đặc) <5 ml; MMA basic <5 ml; SAW <10 ml; FCAW <15 ml. MMA chung (rutile, cellulosic) cao.','(†) MMA que basic cũng <5 ml, nhưng "MMA" nói chung bao gồm que hydro cao.'),
M(9,'P2-19. What information would be required to determine the pre heat level?',['Joint type','shielding gas type','polarity used','CE value','welding position','welding process','heat input','electrode size'],[0,3,5,6],'Cần thông tin gì để xác định mức gia nhiệt?',['Kiểu mối nối (chiều dày tổng hợp)','loại khí bảo vệ','cực tính','giá trị CE','tư thế hàn','quá trình hàn (mức hydro)','nhiệt lượng đưa vào','cỡ que'],'EN 1011-2: CE + chiều dày tổng hợp (theo kiểu mối nối) + mức hydro (do quá trình/vật liệu hàn quyết định) + heat input.','(†) Quá trình hàn được chọn vì nó quyết định mức hydro.'),
M(2,'P2-20. Which of the following MMA electrode types would be suitable to avoid the risk of HICC?',['E6010','E7018','E6011','E8018','E6012','E6013'],[1,3],'Loại que MMA nào phù hợp để tránh nguy cơ HICC?',['E6010','E7018','E6011','E8018','E6012','E6013'],'Số cuối 8 (và 5, 6) = basic hydro thấp. 0, 1 = cellulosic (hydro rất cao); 2, 3 = rutile.'),
M(8,'P2-21. Which of the following could be used to prevent solidification cracking?',['Use a low dilution welding process','Pre heat','add manganese to filler material','PWHT','use a low hydrogen process','depth to width ratio above 2:1'],[0,2],'Biện pháp nào chống nứt kết tinh?',['Dùng quá trình pha loãng thấp','Gia nhiệt sơ bộ','thêm mangan vào vật liệu hàn','PWHT','dùng quá trình hydro thấp','tỉ lệ sâu/rộng trên 2:1'],'Nứt kết tinh: giảm S, P (pha loãng thấp, vật liệu sạch), thêm Mn (tạo MnS), tỉ lệ sâu/rộng < 2:1, giảm kìm hãm. Gia nhiệt, PWHT, hydro thấp là của nứt hydro.'),
M(8,'P2-22. Which of the following are not solidification cracking preventative measures?',['Minimise stress','pre set joint','use low sulphur content material','use stringer beads','use a short arc length','clean joint of contaminants'],[1,3,4],'Biện pháp nào KHÔNG phải là phòng nứt kết tinh?',['Giảm ứng suất','đặt trước mối nối','dùng vật liệu ít lưu huỳnh','dùng đường hàn kéo thẳng (stringer)','dùng hồ quang ngắn','làm sạch mối nối'],'Phòng nứt kết tinh: giảm ứng suất/kìm hãm, S thấp, làm sạch dầu mỡ sơn, tỉ lệ sâu/rộng đúng. Đặt trước (chống biến dạng), hồ quang ngắn (chống rỗ), stringer (không liên quan) không phải biện pháp.','(†) Đáp án dựa trên danh sách biện pháp của WIS5 17.4 và sổ tay tóm tắt.'),
M(8,'P2-23. Which of the following is not something used to avoid Lamellar tearing.',['Avoid restraint','use a forged tee section','use a temper bead technique','butter weld faces','change joint design','minimise stress and restraint'],[2],'Biện pháp nào KHÔNG dùng để tránh rách lớp?',['Tránh kìm hãm','dùng đoạn chữ T rèn','dùng kỹ thuật đường hàn ram (temper bead)','đắp lớp đệm (buttering) mặt hàn','đổi thiết kế mối nối','giảm ứng suất và kìm hãm'],'Rách lớp: thép Z (STRA cao), buttering, đổi thiết kế (tránh kéo theo chiều dày), chi tiết rèn, giảm kìm hãm. Temper bead dùng để ram HAZ cứng (sửa chữa không PWHT).'),
M(8,'P2-24. Lamellar tearing is more likely in which of the following?',['5mm thick tee joint','10mm thick double vee butt joint','10mm double U butt','50mm thick tee butt joint','60mm thick double vee butt joint','100mm thick tee butt joint'],[3,5],'Rách lớp dễ xảy ra ở mối nào?',['Mối T dày 5 mm','mối giáp mối 2V dày 10 mm','mối 2U dày 10 mm','mối T giáp mối dày 50 mm','mối 2V giáp mối dày 60 mm','mối T giáp mối dày 100 mm'],'Rách lớp cần ứng suất THEO CHIỀU DÀY tấm (mối chữ T, mối góc) + tấm DÀY bị kìm hãm. Mối giáp mối không kéo theo chiều dày.'),
M(8,'P2-25. Which of the following is not connected with weld decay?',['Chromium carbide','sensitisation','iron sulphides','stabilised','manganese sulphide','iron carbide','chevron','inter granular corrosion'],[2,4,5,6],'Thứ nào KHÔNG liên quan đến weld decay?',['Cacbit crom','nhạy hóa','sunfua sắt','ổn định hóa','sunfua mangan','cacbit sắt','vết chevron','ăn mòn giữa hạt'],'Weld decay = nhạy hóa → cacbit crom ở biên hạt → ăn mòn giữa hạt; chống bằng L grade hoặc mác ổn định hóa. Sunfua sắt/mangan (nứt kết tinh), cacbit sắt (thép cacbon), chevron (mặt gãy giòn) không liên quan.'),
M(8,'P2-26. For a stainless steel to be classed as low carbon, what percentage carbon does it have to be below?',['0.1%','0.09%','0.04%','0.05%','0.08%','0.07%','0.06%'],[2],'Thép không gỉ được xếp loại cacbon thấp khi cacbon dưới bao nhiêu %?',['0,1%','0,09%','0,04%','0,05%','0,08%','0,07%','0,06%'],'Slide Handout: "Use low carbon stainless steels (below 0.04%)". (Tiêu chuẩn 304L/316L thực tế ≤0,03%; 304 thường ≤0,08%.)'),
M(10,'P3-16. Restraint can help prevent distortion but what else does it increase?',['Porosity','heat input','residual stress','fatigue','bending','yield strength'],[2],'Kìm hãm giúp chống biến dạng nhưng làm tăng gì?',['Rỗ','nhiệt lượng đưa vào','ứng suất dư','mỏi','uốn','giới hạn chảy'],'WIS5 19.4.2: kìm hãm tạo ứng suất dư cao hơn → nguy cơ nứt cao hơn. Biến dạng và ứng suất dư là hai mặt đối nghịch.'),
M(10,'P3-17. Which of the following properties has an effect on distortion?',['Thermal conductivity','yield value','elongation','impact value','coefficient of thermal expansion','relative density'],[0,1,4],'Tính chất nào ảnh hưởng đến biến dạng?',['Độ dẫn nhiệt','giới hạn chảy','độ giãn dài','giá trị va đập','hệ số giãn nở nhiệt','khối lượng riêng tương đối'],'WIS5: hệ số giãn nở nhiệt, độ dẫn nhiệt và (ít hơn) giới hạn chảy, mô đun Young.'),
M(9,'P3-18. What is the correct temperature for annealing C-Mn steel?',['200°c','500°c','650°c','700°c','750°c','800°c','850°c','720°c','920°c'],[8],'Nhiệt độ ủ đúng cho thép C-Mn?',['200 °C','500 °C','650 °C','700 °C','750 °C','800 °C','850 °C','720 °C','920 °C'],'Slide Handout: ủ 920 °C giữ đủ thời gian (austenit hóa hoàn toàn), nguội chậm trong lò. Sách: ~900 °C.'),
M(9,'P3-19. What is the correct temperature range for PWHT?',['250°c - 300°c','350°c - 450°c','400°c - 500°c','550°c - 650°c','750°c - 850°c','900°c - 950°c'],[3],'Khoảng nhiệt độ PWHT đúng?',['250–300 °C','350–450 °C','400–500 °C','550–650 °C','750–850 °C','900–950 °C'],'Khử ứng suất thép C-Mn: 550–650 °C (thường ~600 °C), không chuyển biến pha.'),
M(2,'P3-20. Electrodes classified to AWS 5.1 display the following in their designation?',['Yield strength','Rm value','welding position','charpy impact value','CTOD value','proof stress','flux type'],[1,2,6],'Que phân loại theo AWS A5.1 thể hiện những gì trong ký hiệu?',['Giới hạn chảy','giá trị Rm (bền kéo)','tư thế hàn','giá trị va đập Charpy','giá trị CTOD','giới hạn chảy quy ước','loại thuốc bọc'],'E70 1 8: 70 = bền kéo tối thiểu (Rm, ksi); 1 = tư thế; 8 = loại thuốc/dòng. AWS A5.1 không ghi giới hạn chảy (ISO 2560-A mới ghi).'),
M(2,'P3-21. Basic electrodes, unless they are in a vacuum pack, require baking and then kept warm before use, which of the following are the correct temperatures for this?',['350°c','200°c','100°c','150°c','75°c','50°c'],[0,3,4],'Que basic (trừ loại đóng gói chân không) phải sấy rồi giữ ấm trước khi dùng. Các nhiệt độ đúng là?',['350 °C','200 °C','100 °C','150 °C','75 °C','50 °C'],'Sấy 350 °C → tủ giữ nhiệt 150 °C → bình mang theo (quiver) ~75 °C.'),
M(1,'P3-22. Some of the advantages of TIG welding are?',['High deposition rate compared to MIG/MAG','low hydrogen levels produced','no spatter','easy slag removal','high operational percentage','high toleration of contaminants'],[1,2],'Ưu điểm của hàn TIG?',['Tốc độ đắp cao hơn MIG/MAG','hydro rất thấp','không bắn tóe','dễ gỡ xỉ','hệ số làm việc cao','chịu được bề mặt bẩn'],'TIG: chất lượng cao, hydro thấp nhất (<3 ml), không bắn tóe, không xỉ (nên "dễ gỡ xỉ" sai). Tốc độ đắp thấp, rất nhạy bẩn.'),
M(1,'P3-23. Some of the disadvantages of TIG welding are?',['Low deposition rates','slag inclusions','not all positional','low toleration to contaminants','high skill required','lack of fusion in Dip'],[0,3,4],'Nhược điểm của hàn TIG?',['Tốc độ đắp thấp','ngậm xỉ','không hàn được mọi tư thế','kém chịu bẩn','đòi hỏi tay nghề cao','không ngấu ở chế độ dip'],'TIG hàn được mọi tư thế, không có xỉ, không có chế độ dip (đó là MIG/MAG).'),
M(1,'P3-24. Which of the following are constant during the MIG/MAG process?',['Voltage','gas flow rate','CTWD','wire feed speed','travel speed'],[0,1,3],'Đại lượng nào không đổi trong quá trình MIG/MAG?',['Điện áp','lưu lượng khí','tầm với điện cực (CTWD)','tốc độ cấp dây','tốc độ hàn'],'Nguồn CV giữ điện áp, bộ cấp dây giữ tốc độ dây, lưu lượng kế giữ khí. CTWD và tốc độ hàn do tay thợ nên thay đổi (CTWD đổi → dòng đổi).','(†) Slide Handout section 13 QU3: "voltage and wire feed speed" là cặp không đổi.'),
M(1,'P3-25. In MIG/MAG pulse welding, which of the following adjustments would increase heating on the surface of the weld.',['increase pulse height','increase background time','decrease background height','decrease pulse height','increase background height'],[4],'Trong hàn MIG/MAG xung, điều chỉnh nào làm tăng nhiệt trên bề mặt mối hàn?',['tăng biên độ xung','tăng thời gian nền','giảm dòng nền','giảm biên độ xung','tăng dòng nền'],'Dòng xung (peak) tách giọt và quyết định độ ngấu; dòng NỀN (background, 20–80 A) duy trì hồ quang và làm nóng bề mặt vũng hàn. Tăng dòng nền → bề mặt nóng hơn, vũng rộng hơn.','(†) Đề không có tài liệu đáp án; suy luận theo vai trò dòng nền trong WIS5 13.2.')
]};
})();
